package me.pikanote.companion;
import android.content.*;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.OpenableColumns;import java.io.*;import java.util.*;
public final class MemoryShareProvider extends ContentProvider{
 public boolean onCreate(){return true;}
 File resolve(Uri uri)throws FileNotFoundException{List<String> parts=uri.getPathSegments();if(!Objects.equals(uri.getAuthority(),getContext().getPackageName()+".memory-share")||parts.size()!=2||!parts.get(0).matches("[a-f0-9-]{36}")||!Arrays.asList("transcript.txt","recording.wav").contains(parts.get(1)))throw new FileNotFoundException("Invalid share URI");try{File root=new File(getContext().getCacheDir(),"memory-shares").getCanonicalFile(),f=new File(new File(root,parts.get(0)),parts.get(1)).getCanonicalFile();if(!f.getPath().startsWith(root.getPath()+File.separator)||!f.isFile())throw new FileNotFoundException("Shared file expired");return f;}catch(IOException e){throw new FileNotFoundException(e.getMessage());}}
 public String getType(Uri uri){try{return resolve(uri).getName().endsWith(".wav")?"audio/wav":"text/plain";}catch(FileNotFoundException e){return null;}}
 public Cursor query(Uri uri,String[] projection,String selection,String[] args,String order){try{File f=resolve(uri);String[] columns=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor c=new MatrixCursor(columns);Object[] values=new Object[columns.length];for(int i=0;i<columns.length;i++)values[i]=OpenableColumns.DISPLAY_NAME.equals(columns[i])?f.getName():OpenableColumns.SIZE.equals(columns[i])?f.length():null;c.addRow(values);return c;}catch(FileNotFoundException e){throw new IllegalArgumentException(e.getMessage());}}
 public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{if(!"r".equals(mode))throw new FileNotFoundException("Read-only share");return ParcelFileDescriptor.open(resolve(uri),ParcelFileDescriptor.MODE_READ_ONLY);}
 public Uri insert(Uri u,ContentValues v){throw new SecurityException("Read-only share");}public int update(Uri u,ContentValues v,String s,String[] a){throw new SecurityException("Read-only share");}public int delete(Uri u,String s,String[] a){throw new SecurityException("Read-only share");}
}
